import JSZip from 'jszip';
import fileSaver from 'file-saver';

import {
  buildMarkdownExport,
  buildSavedCardManifestItem,
  parseExportedMarkdownPrompt,
} from './cardCodec.js';

const { saveAs } = fileSaver;

const SOURCE_PROJECT = 'virtual-photography-studio';

function archiveIdDescriptor(prompt, index) {
  const sourceId = String(prompt?.id || '').trim() || `item-${index + 1}`;
  const safeId = sourceId
    .replace(/[^a-zA-Z0-9._-]/g, '_')
    .slice(0, 96) || `item-${index + 1}`;
  return {
    sourceId,
    safeId,
    baseFile: `prompt_${safeId}.md`,
  };
}

function shortArchiveHash(value) {
  let hash = 2166136261;
  const text = String(value || '');
  for (let index = 0; index < text.length; index += 1) {
    hash ^= text.charCodeAt(index);
    hash = Math.imul(hash, 16777619);
  }
  return (hash >>> 0).toString(16).padStart(8, '0');
}

export function buildArchiveFileNames(items) {
  const descriptors = (Array.isArray(items) ? items : []).map(archiveIdDescriptor);
  const groups = new Map();
  descriptors.forEach((descriptor) => {
    const group = groups.get(descriptor.baseFile) || [];
    group.push(descriptor);
    groups.set(descriptor.baseFile, group);
  });

  const used = new Set();
  return descriptors.map((descriptor) => {
    const group = groups.get(descriptor.baseFile) || [];
    const needsDisambiguation = group.length > 1;
    const hash = shortArchiveHash(descriptor.sourceId);
    let file = needsDisambiguation
      ? `prompt_${descriptor.safeId}_${hash}.md`
      : descriptor.baseFile;
    let suffix = 2;
    while (used.has(file)) {
      file = `prompt_${descriptor.safeId}_${hash}_${suffix}.md`;
      suffix += 1;
    }
    used.add(file);
    return file;
  });
}

function getExportableItems(items) {
  return (Array.isArray(items) ? items : [])
    .filter((prompt) => prompt && typeof prompt === 'object' && String(prompt.id || '').trim());
}

function normalizeArchivePath(path) {
  return String(path || '').replace(/^\.\//, '').replace(/\\/g, '/');
}

function findManifestItem(manifestItems, entryName) {
  const normalizedEntryName = normalizeArchivePath(entryName);
  const entryBaseName = normalizedEntryName.split('/').pop();
  return manifestItems.find((item) => {
    const itemFile = normalizeArchivePath(item?.file);
    return itemFile === normalizedEntryName || itemFile.split('/').pop() === entryBaseName;
  }) || null;
}

export async function createSavedCardsArchive(items, now = Date.now(), type = 'blob') {
  const exportItems = getExportableItems(items);
  if (exportItems.length === 0) return null;

  const zip = new JSZip();
  const manifestItems = [];
  const files = buildArchiveFileNames(exportItems);
  exportItems.forEach((prompt, index) => {
    const file = files[index];
    zip.file(file, buildMarkdownExport(prompt));
    manifestItems.push(buildSavedCardManifestItem(prompt, file));
  });
  zip.file('manifest.json', JSON.stringify({
    schemaVersion: 1,
    sourceProject: SOURCE_PROJECT,
    exportedAt: new Date(now).toISOString(),
    items: manifestItems,
  }, null, 2));
  return zip.generateAsync({ type });
}

export async function downloadSavedCardsArchive(items, now = Date.now()) {
  const content = await createSavedCardsArchive(items, now, 'blob');
  if (!content) return false;
  saveAs(content, `virtual_photography_prompts_${now}.zip`);
  return true;
}

export async function parseSavedCardsArchive(file, controls) {
  const zip = await JSZip.loadAsync(file);
  const manifestEntry = Object.values(zip.files).find((entry) => (
    !entry.dir && normalizeArchivePath(entry.name).toLowerCase() === 'manifest.json'
  ));
  let manifest = null;
  if (manifestEntry) {
    try {
      manifest = JSON.parse(await manifestEntry.async('string'));
    } catch {
      throw new Error('manifest.json is invalid');
    }
  }

  const manifestItems = Array.isArray(manifest?.items) ? manifest.items : [];
  const markdownEntries = Object.values(zip.files)
    .filter((entry) => !entry.dir && entry.name.toLowerCase().endsWith('.md'))
    .sort((a, b) => a.name.localeCompare(b.name));

  if (markdownEntries.length === 0) {
    throw new Error('zip does not contain exported markdown prompts');
  }

  const importedPrompts = [];
  for (const entry of markdownEntries) {
    const markdown = await entry.async('string');
    const idMatch = entry.name.match(/prompt_(.+)\.md$/i);
    const fallbackId = idMatch?.[1] || `${Date.now()}-${importedPrompts.length}`;
    const manifestItem = findManifestItem(manifestItems, entry.name);
    const parsedPrompt = parseExportedMarkdownPrompt(markdown, controls, manifestItem?.sourceId || fallbackId);
    importedPrompts.push({
      ...parsedPrompt,
      sourceProject: manifest?.sourceProject || '',
      sourceId: manifestItem?.sourceId || fallbackId,
      sourceFileName: entry.name,
      sourceTags: Array.isArray(manifestItem?.tags) ? manifestItem.tags : [],
    });
  }
  return importedPrompts;
}

import assert from 'node:assert/strict';
import test from 'node:test';
import JSZip from 'jszip';

import { createEmptyLocks, generatePrompts, getLockControls } from '../../lib/engine.js';
import {
  buildMarkdownExport,
} from './cardCodec.js';
import {
  buildArchiveFileNames,
  createSavedCardsArchive,
  parseSavedCardsArchive,
} from './savedCardArchive.js';

function createPrompt(id) {
  const [prompt] = generatePrompts(1, createEmptyLocks(), [], { random: () => 0.123456 });
  return {
    ...prompt,
    id,
    date: '2026-07-15T00:00:00.000Z',
    title: `Prompt ${id}`,
  };
}

test('saved card archive contains manifest and unchanged markdown exports', async () => {
  const prompt = createPrompt('archive-one');
  const bytes = await createSavedCardsArchive([prompt], 0, 'uint8array');
  const zip = await JSZip.loadAsync(bytes);
  const names = Object.keys(zip.files).sort();

  assert.deepEqual(names, ['manifest.json', 'prompt_archive-one.md']);

  const manifest = JSON.parse(await zip.file('manifest.json').async('string'));
  assert.equal(manifest.schemaVersion, 1);
  assert.equal(manifest.sourceProject, 'virtual-photography-studio');
  assert.equal(manifest.exportedAt, '1970-01-01T00:00:00.000Z');
  assert.equal(manifest.items.length, 1);
  assert.equal(manifest.items[0].sourceId, 'archive-one');
  assert.equal(manifest.items[0].file, 'prompt_archive-one.md');
  assert.deepEqual(Object.keys(manifest.items[0].summaryFields), [
    'style', 'character', 'wardrobe', 'location', 'camera', 'lighting',
  ]);

  const markdown = await zip.file('prompt_archive-one.md').async('string');
  assert.equal(markdown, buildMarkdownExport(prompt));
});

test('archive file names stay unique for sanitized id collisions and invalid items are skipped', async () => {
  const prompts = [
    createPrompt('a/b'),
    createPrompt('a_b'),
    createPrompt('a b'),
  ];
  const names = buildArchiveFileNames(prompts);
  assert.equal(new Set(names).size, prompts.length);
  assert.ok(names.every((name) => /^prompt_[a-zA-Z0-9._-]+\.md$/.test(name)));

  const bytes = await createSavedCardsArchive([null, { id: '' }, ...prompts], 1, 'uint8array');
  const zip = await JSZip.loadAsync(bytes);
  const manifest = JSON.parse(await zip.file('manifest.json').async('string'));
  assert.equal(manifest.items.length, 3);
  assert.equal(new Set(manifest.items.map((item) => item.file)).size, 3);
  assert.equal(Object.keys(zip.files).filter((name) => name.endsWith('.md')).length, 3);
});

test('manifest sourceId restores safe-filename exports while old markdown-only archives remain importable', async () => {
  const prompt = createPrompt('原始/卡片');
  const controls = getLockControls();

  const manifestBytes = await createSavedCardsArchive([prompt], 2, 'uint8array');
  const restored = await parseSavedCardsArchive(manifestBytes, controls);
  assert.equal(restored.length, 1);
  assert.equal(restored[0].id, '原始/卡片');
  assert.equal(restored[0].sourceId, '原始/卡片');

  const legacyZip = new JSZip();
  legacyZip.file('prompt_legacy-card.md', buildMarkdownExport(createPrompt('legacy-card')));
  const legacyBytes = await legacyZip.generateAsync({ type: 'uint8array' });
  const importedLegacy = await parseSavedCardsArchive(legacyBytes, controls);
  assert.equal(importedLegacy.length, 1);
  assert.equal(importedLegacy[0].id, 'legacy-card');
});

test('legacy markdown archive without a snapshot restores Midjourney tail settings and aspect ratio', async () => {
